# Generated by scripts/release.sh tap from packaging/homebrew/yt-music-player.rb in
# https://github.com/xlanstar/yt-music-player. Do not edit in the tap; change the template instead.
cask "yt-music-player" do
  version "@VERSION@"
  sha256 "@SHA256@"

  url "https://github.com/xlanstar/yt-music-player/releases/download/v#{version}/YT-Music-Player-#{version}-macos-universal.dmg"
  name "YT Music Player"
  desc "Lightweight YouTube Music player"
  homepage "https://github.com/xlanstar/yt-music-player"

  livecheck do
    url :url
    strategy :github_latest
  end

  # The app installs its updates itself; brew upgrades only an app that
  # did not.
  auto_updates true
  depends_on macos: :monterey

  app "YT Music Player.app"
  binary "#{appdir}/YT Music Player.app/Contents/Resources/ytm"

  # early_script stops the background player with the app's ytm before the
  # app goes. Homebrew runs these on upgrades too, so starting the player
  # at login (its LaunchAgent) is undone only by zap, not on every upgrade;
  # once the app is gone, the LaunchAgent removes itself at the next login.
  uninstall early_script: {
              executable:   "#{appdir}/YT Music Player.app/Contents/Resources/ytm",
              args:         ["daemon", "stop"],
              must_succeed: false,
            },
            quit:         "dev.lanstar.ytmusicplayer"

  # launchctl removes the background player's LaunchAgent and its plist;
  # the script forgets the sign-in, a Keychain item of service
  # yt-music-player.
  zap launchctl: "dev.lanstar.ytmusicplayer.daemon",
      script:    {
        executable:   "/usr/bin/security",
        args:         ["delete-generic-password", "-s", "yt-music-player"],
        must_succeed: false,
      },
      trash:     [
        "~/Library/Application Support/YT Music Player",
        "~/Library/Application Support/yt-music-player",
        "~/Library/Caches/yt-music-player",
        "~/Library/HTTPStorages/dev.lanstar.ytmusicplayer",
        "~/Library/Preferences/dev.lanstar.ytmusicplayer.plist",
        "~/Library/Saved Application State/dev.lanstar.ytmusicplayer.savedState",
      ]
end
